# A line whose product has left the catalog is skipped rather than
# failing the whole basket.
def cart_subtotal(cart: List[Line]) -> Result[Int, Text] =
  match cart {
    [] => Ok(0),
    [l, ..rest] => {
      let head = match line_cost(l) {
        Ok(c) => c,
        Err(_) => 0,
      };
      let tail = cart_subtotal(rest)?;
      Ok(head + tail)
    },
  }

